Context - 资深码农 ~$ 资深码农 后端 数据库 AI 运维 前端 工具 游戏 系统 更多 主页 / 后端与编程语言 / Go 语言总览 / Context Go Context 📅 2026-09-18 🏷️ Go 语言 context 是什么，不是什么 很多人学 context 只学了"传超时"，其实它干三件事： 管 goroutine 的生死、带请求级的元数据、传取消信号 。一句话定位：谁派生的，谁就得负责取消。 它最核心的哲学是 协作式取消 ——它不会硬杀 goroutine，只是发个信号说"活干完了，收工"。goroutine 得自己监听 ctx.Done() 然后主动退出。你不监听，信号就白搭。 我常打的比方 context 就像对讲机。老板（父 context）喊"下班了"，所有下属 goroutine 都能在对讲机里听到。但你要是戴着耳机不听，喊破喉咙也没用——goroutine 泄漏十有八九就是这个原因。 四个派生函数，一张树图 Context 接口就四个方法，看着简单： type Context interface {
    Deadline() (deadline time.Time, ok bool)
    Done() <-chan struct{}
    Err() error
    Value(key any) any
} 根节点只有两个： context.Background() （一切的起点，永不取消）和 context.TODO() （占位，上线前换掉）。从根上派生子 context 长成长，取消信号只能父→子传，子捅不破父。 取消信号怎么从父 context 一路传到最底层的 goroutine，时序长这样： 派生函数 取消方式 cancel 必须调? 什么时候用 WithCancel 手动 cancel 必须 手动收一批 goroutine WithTimeout 超时自动 + 手动 必须 HTTP 请求、RPC 调用 WithDeadline 到点自动 + 手动 必须 对齐上游绝对时间 WithValue 不可取消 不需要 传 requestID / traceID HTTP 请求里怎么用 HTTP handler 里拿 r.Context() 当父链，客户端断了或者超时了，下游查数据库跟着取消——不会傻等： func handler(w http.ResponseWriter, r *http.Request) {
    ctx, cancel := context.WithTimeout(r.Context(), 3*time.Second)
    defer cancel()

    result, err := fetchFromDB(ctx, query)
    if err != nil {
        if ctx.Err() == context.DeadlineExceeded {
            http.Error(w, "timeout", http.StatusGatewayTimeout)
            return
        }
        http.Error(w, err.Error(), http.StatusInternalServerError)
        return
    }
    json.NewEncoder(w).Encode(result)
} goroutine 取消用 select 监听 ctx.Done() ： func worker(ctx context.Context, id int) {
    for {
        select {
        case <-ctx.Done():
            fmt.Printf("worker %d stop: %v\n", id, ctx.Err())
            return
        default:
            time.Sleep(500 * time.Millisecond)
        }
    }
}

func main() {
    ctx, cancel := context.WithCancel(context.Background())
    for i := 1; i <= 3; i++ { go worker(ctx, i) }
    time.Sleep(2 * time.Second)
    cancel()
} 血泪教训 最常见的泄漏：你起 goroutine 调 DB，结果 DB 驱动的方法没

Echo v5 - 资深码农 ~$ 资深码农 后端 数据库 AI 运维 前端 工具 游戏 系统 更多 主页 / 后端与编程语言 / Go 语言总览 / Echo v5 Echo v5 📅 2026-09-18 🏷️ Go 语言 Echo 2026 年什么定位 我前两年还劝人别用 Echo，说等 Fiber/Huma 出来再换。结果 2026 年反转了—— Echo v5 在 2026 年 1 月成了 latest major （2026-08 最新 v5.3.x，32.6k+ stars），和 Gin、Fiber 重新三足鼎立。这篇我先给你一套生产用过的页面缓存方案，再讲 v5 升级要注意什么。 核心思路 读在 Nginx、写在 Echo。Nginx 的 memcached_pass 负责缓存命中时的零进程读取，Echo 中间件负责未命中时把响应写回缓存。动静分离，缓存逻辑和业务解耦。 页面级缓存：Nginx + Echo + Memcached 这套方案我在线上跑过一年，QPS 从 2000 干到 8000，Go 进程 CPU 没涨——因为读请求根本不进 Go。先看整体流程： 为什么这么拆？读侧 Nginx 扛，命中即返回，Go 进程零开销；写侧才真正跑 handler。你要是在 Go 里自己写"命中即 return"，读请求还是要进 Go 进程，白搭。 中间件实现 下面这个中间件包装 http.ResponseWriter ，把 200 响应的 body 缓冲进 Memcached： import (
 "bytes"
 "net/http"
 "sync"

 "github.com/bradfitz/gomemcache/memcache"
 "github.com/labstack/echo/v4"
)

var memcacheClientMux sync.Mutex
var memcacheClient *memcache.Client

type middleResp struct {
 http.ResponseWriter
 isOK       bool
 key        string
 expiration int32
 bytes.Buffer
}

var StoreErrHandler func(error)

func (mr *middleResp) writeStore() {
 if mr.Buffer.Len() > 0 {
  err := memcacheClient.Set(&memcache.Item{
   Key:        mr.key,
   Flags:      0,
   Expiration: mr.expiration,
   Value:      mr.Bytes(),
  })
  if StoreErrHandler != nil {
   StoreErrHandler(err)
  }
 }
}

func (mr *middleResp) Write(body []byte) (int, error) {
 if mr.isOK && memcacheClient != nil {
  _, err := mr.Buffer.Write(body)
  if StoreErrHandler != nil {
   StoreErrHandler(err)
  }
 }
 return mr.ResponseWriter.Write(body)
}

func (mr *middleResp) WriteHeader(statusCode int) {
 mr.isOK = statusCode == http.StatusOK
 mr.ResponseWriter.WriteHeader(statusCode)
}

