INSERT INTO mvcc_demo VALUES (1, 100);
BEGIN;
UPDATE mvcc_demo SET amt = 200 WHERE id = 1;
-- 在另一个会话：
SELECT xmin, xmax, id, amt FROM mvcc_demo WHERE id = 1;
-- 你会看到两行：
--  xmin=72  xmax=73  id=1  amt=100 < - 旧版本（已被本事务标记删除）
--  xmin=73  xmax=0   id=1  amt=200 < - 新版本
COMMIT;
-- commit 后，旧版本对新快照不可见，但物理上还在，等 Vacuum 回收 四种隔离级别 SQL 标准定义了四种隔离级别，PostgreSQL 全部支持： Read Committed（默认） ：每条语句都看到最新提交的快照。单条语句内一致，事务内两条相同查询可能结果不同。 Repeatable Read ：整个事务看到第一次快照。本事务开始后别人提交的修改看不见。 Serializable（SSI） ：Serializable Snapshot Isolation，用 SI 加危险结构检测，能防止写偏序（write skew），代价是可能序列化失败让你重试。 -- 会话 A：转账 100 给账户 2
BEGIN ISOLATION LEVEL READ COMMITTED;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;

-- 会话 B：Repeatable Read 下的现象演示
BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT sum(balance) FROM accounts;   -- 看到 A 转账前的总和
-- 此时 A 提交转账
SELECT sum(balance) FROM accounts;   -- 仍然看到旧总和（快照不变）
COMMIT;

