// ref：包装任意类型，模板里自动解包，脚本里用 .value
const count = ref(0);
const doubled = computed(() => count.value * 2);

// reactive：包装对象/数组，直接修改属性
const state = reactive({
  user: { name: "junjunyi" },
  list: [1, 2, 3],
});

// 侦听：source 可以是 ref/getter/多个源
watch(count, (newVal, oldVal) => {
  console.log(`count: ${oldVal} -> ${newVal}`);
});

// 直接修改，界面自动更新
function increment() {
  count.value++;
  state.user.name = "updated";
} 选择原则： 基础类型用 ref，对象用 reactive（或 ref） 。团队规范通常是"统一用 ref"，避免 reactive 解构丢失响应式的坑。 2.2 Composable：逻辑复用的终极形态 Composition API 的杀手锏是 composable 函数——把一段有状态的逻辑抽出来，像自定义 Hook 一样在多个组件间复用： // composables/useMouse.ts
import { ref, onMounted, onUnmounted } from "vue";

export function useMouse() {
  const x = ref(0);
  const y = ref(0);

  function update(e: MouseEvent) {
    x.value = e.pageX;
    y.value = e.pageY;
  }

  onMounted(() => window.addEventListener("mousemove", update));
  onUnmounted(() => window.removeEventListener("mousemove", update));

  return { x, y };
}

