数组与链表 - 资深码农 ~$ 资深码农 后端 数据库 AI 运维 前端 工具 游戏 系统 更多 主页 / 更多技术 / 数组与链表 数组与链表 📅 2026-09-17 🏷️ 算法,数组,链表 线性表的两大基石 数组（Array）和链表（Linked List）是所有线性结构的起点，也是面试出现频率最高的考点之一。它们的本质区别只有一句话： 数组用一段连续内存存储元素，支持 O(1) 随机访问；链表用指针串联散落内存，插入删除 O(1) 但访问要 O(n) 遍历 。这个差异决定了它们各自的擅长领域——数组适合"读多写少、按下标访问"，链表适合"频繁插入删除、不需要随机访问"。 很多人觉得"链表手写过就懂了"，但工程上真正难的是 边界条件处理 ：空指针、单节点、头尾插入、循环终止条件。90% 的链表 bug 都出在指针还没赋值就被使用、或者 while 循环少判了一个条件。 内存布局对比 数组在内存中是连续的一块，CPU 缓存预取友好，访问极快；链表节点散落在堆上，每个节点多存一个指针（8 字节），且访问下一个节点常常缓存不命中。下图直观对比两者的内存模型： 数组的关键操作 随机访问 ： arr[i] 直接算出地址 base + i×size，O(1)。 尾部追加 ：均摊 O(1)（需扩容时拷贝）。 中间插入/删除 ：要挪动后续元素，平均 O(n)。 扩容策略 ：Go slice 按 2 倍（小容量）/1.25 倍（大容量）增长，Java ArrayList 1.5 倍，Python list 约 1.125 倍。 链表的关键操作 已知前驱节点处插入 ：改两个指针即可，O(1)。 头插法建链表 ：O(1)，常用于反转、LFRU 等。 查找/按索引访问 ：只能从头遍历，O(n)。 删除节点 ：若直接拿到待删节点，可以用"后继覆盖"技巧 O(1) 删除（不删尾节点）。 经典例题 1：反转单链表 反转链表是面试必考题，核心是 三指针逐个翻转 next 指向 。用"哑节点 + 三指针"模板可以从容应对大多数链表题。迭代写法比递归更优（无递归栈开销），也是工程首选： package main

import "fmt"

type ListNode struct {
    Val  int
    Next *ListNode
}

// reverseList 迭代反转单链表：O(n) 时间，O(1) 空间
func reverseList(head *ListNode) *ListNode {
    var prev *ListNode
    curr := head
    for curr != nil {
        next := curr.Next // 暂存下一个
        curr.Next = prev  // 反转指针
        prev = curr       // 前进一步
        curr = next
    }
    return prev
}

// 辅助：从切片构造链表并打印
func build(vals []int) *ListNode {
    dummy := &ListNode{}
    tail := dummy
    for _, v := range vals {
        tail.Next = &ListNode{Val: v}
        tail = tail.Next
    }
    return dummy.Next
}
func printList(head *ListNode) {
    for p := head; p != nil; p = p.Next {
        fmt.Print(p.Val, " -> ")
    }
    fmt.Println("nil")
}

func main() {
    head := build([]int{1, 2, 3, 4, 5})
    printList(head)          // 1 -> 2 -> 3 -> 4 -> 5 -> nil
    printList(reverseList(head)) // 5 -> 4 -> 3 -> 2 -> 1 -> nil
} Python 对照实现： from typing import Optional

