func dfs(grid [][]byte, r, c int) {
    m, n := len(grid), len(grid[0])
    // 越界或不是陆地，直接返回
    if r < 0 || r >= m || c < 0 || c >= n || grid[r][c] != '1' {
        return
    }
    grid[r][c] = '0' // 标记已访问（沉没）
    dfs(grid, r-1, c)
    dfs(grid, r+1, c)
    dfs(grid, r, c-1)
    dfs(grid, r, c+1)
}

